import{S as e,o as t,c as n,a9 as l,B as h}from"./chunks/framework.IJ8axLs_.js";const p="/agentsrc/images/claudecode/03-assembly-pipeline.svg",k="/agentsrc/images/claudecode/03-context-pressure-valves.svg",o="/agentsrc/images/claudecode/03-command-dispatch.svg",E=JSON.parse('{"title":"Claude Code 工具系统拆解：50+ 个工具怎么装进一个接口","description":"","frontmatter":{"title":"Claude Code 工具系统拆解：50+ 个工具怎么装进一个接口"},"headers":[],"relativePath":"claudecode/03-tools.md","filePath":"claudecode/03-tools.md","lastUpdated":1790217011000}'),d={name:"claudecode/03-tools.md"},y=Object.assign(d,{setup(r){const i=[{question:"`buildTool` 的默认值设计里，`isReadOnly` 默认 false 的安全含义是什么？",options:["权限系统默认按写操作检查工具，不会误放只读","工具默认无法读取文件，需要显式声明读权限","UI 渲染默认把工具归类为写操作显示红色标记","调度器默认跳过只读工具以减少并发冲突"],correct:0,explanation:"默认 false 意味着新工具默认被当成会写文件的操作对待，权限检查按写操作的严格度走。反例是默认 true：开发者忘了重写，工具被权限系统当只读放行，漏洞藏在最常见的「忘记写」失误里。fail-closed 把失误方向对准安全一侧——忘了写最多损失性能，不会损失安全性。"},{question:"`assembleToolPool` 里内置工具和 MCP 工具分别排序再 concat，而不是全局扁平排序，原因是？",options:["uniqBy 只能对分段有序的数组做去重","保持内置工具为连续前缀，MCP 变动只失效后段 cache","localeCompare 对带双下划线的 MCP 名字有已知 bug","让 deny 规则的过滤只作用于 MCP 分段以加速装配"],correct:1,explanation:"API 的 prompt caching 按前缀匹配，工具 schema 顺序一变 cache 全灭。内置工具排成连续前缀、MCP 工具作为可变后缀，接入或断开 MCP server 时只有 MCP 段的 cache 失效。扁平排序会让 MCP 工具插进内置工具中间，任何 MCP 变动都移动后面所有工具的位置，下游 cache key 全部报废。"},{question:"`isBridgeSafeCommand` 对三种命令类型的判定，正确的是哪一项？",options:["local-jsx 拒绝、prompt 默认放行、local 需在白名单","local-jsx 默认放行、prompt 需白名单、local 拒绝","三种类型都要逐个进白名单才能远程触发","prompt 与 local-jsx 放行、只有 local 需要白名单"],correct:0,explanation:"local-jsx 要渲染 Ink 组件，手机/网页端没有终端 UI，永远拒绝；prompt 展开成文本发给模型，默认安全；local 有本地副作用，必须进 BRIDGE_SAFE_COMMANDS 显式白名单（目前六个）。这套判定来自 PR #19134 的先全部禁止再逐个放开。"},{question:"FileReadTool 把 `maxResultSizeChars` 设为 `Infinity`，落盘判定里这个值是怎么处理的？",options:["参与阈值覆盖后由 GrowthBook 决定是否落盘","作为硬 opt-out 直接跳过，任何覆盖都不生效","等于 50k 全局默认值，因为 Math.min 会取小","触发 64MB 截断逻辑，只落盘文件前半段"],correct:1,explanation:"getPersistenceThreshold 开头先查 Number.isFinite——Infinity 直接原样返回，GrowthBook 的阈值覆盖拿它没办法。动机：落盘 Read 结果会形成「Read → 落盘文件 → 模型再 Read」的环，而 Read 自己有 maxTokens 截断策略。这个 opt-out 是硬的，注释明确写了 override flag 不能强制它重新开启。"},{question:"Commander.js 在 Claude Code 命令体系里的实际角色是？",options:["只解析 CLI 启动参数，REPL 斜杠命令走独立解析器","统一解析 CLI 参数与 REPL 内的斜杠命令","只负责斜杠命令的子命令与 flag 解析","已被移除，全部命令解析都是手写的"],correct:0,explanation:"Commander.js 在 main.tsx 里只处理 claude --print、--resume 这类启动 flags。REPL 内斜杠命令走 slashCommandParsing.ts 的 60 行极简解析：按空格切，第一词是命令名，剩下的是参数；参数语义由各命令自治解释，不为每个命令维护 flag schema。"}];return(c,s)=>{const a=e("Quiz");return t(),n("div",null,[s[0]||(s[0]=l("",158)),h(a,{questions:i})])}}});export{E as __pageData,y as default};
